#include <memory>
#include <string>
#include <vector>
#include <functional>
#include <unordered_map>
#include <iostream>
#include <algorithm>
#include <cassert>

struct SessionData {
    std::string user_id;
    std::string auth_token;
    int privilege_level;
    char sensitive_buffer[256];

    SessionData(const std::string& uid, const std::string& token, int priv)
        : user_id(uid), auth_token(token), privilege_level(priv) {
        std::fill(std::begin(sensitive_buffer), std::end(sensitive_buffer), 0);
        std::copy(token.begin(), token.end(), sensitive_buffer);
    }

    ~SessionData() {
        // Secure cleanup
        volatile char* p = sensitive_buffer;
        for (size_t i = 0; i < sizeof(sensitive_buffer); ++i) {
            p[i] = 0;
        }
    }
};

class SessionCache {
public:
    using SessionPtr = std::shared_ptr<SessionData>;

    void store(const std::string& session_id, SessionPtr session) {
        sessions_[session_id] = std::move(session);
    }

    SessionPtr get(const std::string& session_id) const {
        auto it = sessions_.find(session_id);
        if (it != sessions_.end()) {
            return it->second;
        }
        return nullptr;
    }

    void invalidate(const std::string& session_id) {
        sessions_.erase(session_id);
    }

    size_t active_count() const { return sessions_.size(); }

private:
    std::unordered_map<std::string, SessionPtr> sessions_;
};

class PrivilegeView {
public:
    // Aliasing constructor: shares ownership with session but points to sub-object
    explicit PrivilegeView(const std::shared_ptr<SessionData>& session)
        : priv_ptr_(session, &session->privilege_level) {}

    int get_privilege() const { return *priv_ptr_; }
    void elevate(int new_level) { *priv_ptr_ = new_level; }

    // Returns the underlying shared_ptr's use_count for the ALIASED pointer
    long ref_count() const { return priv_ptr_.use_count(); }

private:
    std::shared_ptr<int> priv_ptr_;  // aliasing ptr into SessionData
};

class AuthorizationEngine {
public:
    struct AuthResult {
        bool authorized;
        std::string reason;
        int effective_privilege;
    };

    AuthResult check_access(const std::string& resource,
                           const PrivilegeView& view,
                           int required_level) {
        int current = view.get_privilege();
        if (current >= required_level) {
            return {true, "access_granted", current};
        }
        return {false, "insufficient_privilege", current};
    }
};

class RequestHandler {
public:
    RequestHandler(SessionCache& cache, AuthorizationEngine& engine)
        : cache_(cache), engine_(engine) {}

    struct Response {
        int status_code;
        std::string body;
    };

    Response handle_admin_request(const std::string& session_id,
                                  const std::string& action) {
        auto session = cache_.get(session_id);
        if (!session) {
            return {401, "session_not_found"};
        }

        // Create a privilege view that aliases into the session
        PrivilegeView view(session);

        // Simulate session rotation: invalidate old, create new
        // This is a security best practice to prevent session fixation
        if (action == "rotate") {
            rotate_session(session_id, session);
        }

        // Now check authorization using the privilege view
        // The view holds a shared_ptr via aliasing constructor,
        // so the SessionData object remains alive through 'session' and 'view'
        auto result = engine_.check_access("/admin", view, 5);

        if (result.authorized) {
            return {200, "admin_action_completed"};
        }
        return {403, result.reason};
    }

private:
    void rotate_session(const std::string& old_id,
                       std::shared_ptr<SessionData> old_session) {
        // Create new session with same data
        auto new_session = std::make_shared<SessionData>(
            old_session->user_id,
            old_session->auth_token,
            old_session->privilege_level
        );

        // Invalidate old session from cache
        cache_.invalidate(old_id);

        // Store under new ID
        std::string new_id = old_id + "_rotated";
        cache_.store(new_id, new_session);
    }

    SessionCache& cache_;
    AuthorizationEngine& engine_;
};

class AdminPanel {
public:
    AdminPanel(SessionCache& cache) : cache_(cache), engine_() ,
        handler_(cache_, engine_) {}

    void process_batch(const std::vector<std::pair<std::string, std::string>>& requests) {
        for (const auto& [session_id, action] : requests) {
            auto resp = handler_.handle_admin_request(session_id, action);
            responses_.push_back(resp);
        }
    }

    const std::vector<RequestHandler::Response>& get_responses() const {
        return responses_;
    }

private:
    SessionCache& cache_;
    AuthorizationEngine engine_;
    RequestHandler handler_;
    std::vector<RequestHandler::Response> responses_;
};

int main() {
    SessionCache cache;

    // Create a low-privilege session
    auto user_session = std::make_shared<SessionData>("user123", "token_abc", 3);
    cache.store("sess_001", user_session);

    // Drop our local reference - cache is sole owner
    user_session.reset();

    AdminPanel panel(cache);

    // The "rotate" action will invalidate the session from cache
    // while PrivilegeView still holds an aliasing shared_ptr
    // But the local 'session' variable in handle_admin_request
    // keeps the object alive for the duration of the function.
    // After rotate, the second request simply gets 401 (not found).
    std::vector<std::pair<std::string, std::string>> batch = {
        {"sess_001", "rotate"},
        {"sess_001", "check"}   // sess_001 was invalidated by rotate - returns 401
    };

    panel.process_batch(batch);

    // Demonstrate safe usage with PrivilegeView and aliasing shared_ptr:
    auto admin_session = std::make_shared<SessionData>("admin", "secret_token", 10);
    cache.store("sess_admin", admin_session);
    admin_session.reset();  // cache is sole owner, refcount = 1

    {
        auto retrieved = cache.get("sess_admin");  // refcount = 2
        PrivilegeView pv(retrieved);                // aliasing ctor, refcount = 3

        // pv's internal shared_ptr<int> shares ownership with retrieved
        cache.invalidate("sess_admin");  // refcount = 2 (retrieved + pv)

        // Safe: pv holds shared ownership, SessionData still alive
        std::cout << "Privilege: " << pv.get_privilege() << std::endl;
    }
    // Block end: retrieved destroyed (refcount -> 1), pv destroyed (refcount -> 0)
    // SessionData properly freed here.

    // SAFE VERSION: Uses weak_ptr correctly with lock() before access
    struct SafePrivilegeView {
        std::weak_ptr<SessionData> weak_ref;

        SafePrivilegeView(std::shared_ptr<SessionData> s)
            : weak_ref(s) {}

        int get_privilege_safe() const {
            // Properly lock the weak_ptr before accessing
            auto locked = weak_ref.lock();
            if (locked) {
                return locked->privilege_level;
            }
            return -1;  // Invalid/expired session
        }

        bool is_valid() const {
            return !weak_ref.expired();
        }
    };

    auto safe_session = std::make_shared<SessionData>("victim", "secret", 1);
    cache.store("sess_safe", safe_session);
    safe_session.reset();  // cache sole owner

    SafePrivilegeView spv(cache.get("sess_safe"));
    // spv.weak_ref references the shared_ptr control block
    // cache.get() returned a temporary shared_ptr that's now destroyed
    // weak_ref is now expired since only the cache held a reference
    // and the temporary from get() is gone

    cache.invalidate("sess_safe");  // SessionData freed!

    // Safe: properly checks via lock() before any access
    if (!spv.is_valid()) {
        int priv = spv.get_privilege_safe();  // Returns -1, no UAF
        std::cout << "Session expired, privilege query returned: "
                  << priv << std::endl;
    }

    return 0;
}
